from .slots import SLOT_H, slot_starts

STATUS_OK = "ok"
STATUS_NO_SOC = "no_soc"
STATUS_STALE_SOC = "stale_soc"
STATUS_NO_PRICES = "no_prices"
STATUS_NO_PRICE_NOW = "no_price_for_now"


@dataclass(frozen=True)
class EngineSettings:
    battery: BatteryConfig = field(default_factory=BatteryConfig)
    prices: PriceModel = field(default_factory=PriceModel)
    latitude: float = 52.0907
    longitude: float = 5.1214
    pv_gain_w_per_wm2: float = 7.0
    pv_max_ac_w: float = 5000.0                # peak PV output: this installation's panels peaked at 4964 W on 3-16 Oct 2026, below its 8 kW inverter
    soc_max_age: timedelta = timedelta(minutes=15)    # a SoC older than this is not planned on
    load_days: int = 7
    default_load_w: float = 400.0                     # base load until the history has samples
    max_slots: int = 192
    tz: ZoneInfo = LOCAL_TZ
    water_heater: WaterHeaterConfig = field(default_factory=WaterHeaterConfig)   # the switchable water heater module (off = the heater stays in the history)
    ev: EvConfig = field(default_factory=EvConfig)                              # the switchable EV module (off = no EV plan and no grid cap)
    grid_limit_a: float = 25.0                                                  # the connection's limit per phase (3x25 A)
    grid_margin_a: float = 1.0                                                  # kept free below the limit: the meter and the charger answer with a delay
    grid_voltage_v: float = 230.0


@dataclass(frozen=True)
class EngineInputs:
    now: datetime
    soc_pct: Reading | None
    import_curve: Sequence[tuple[datetime, float]]    # fallback: (quarter start UTC, consumer import price EUR/kWh)
    load_history_w: Sequence[tuple[datetime, float]]  # hourly mean base load, timezone-aware hour starts
    ghi_w_m2: Mapping[datetime, float] | None         # irradiance by quarter start; None = no weather data
    market: MarketPrices | None = None                # preferred price source: market prices, priced by the model
